/// Unicode version of these `General_Category`/`Script` tables.
pub const UCD_VERSION: (u8, u8, u8) = (16, 0, 0);

/// Word for codepoints outside the Unicode range (permissive decoding
/// of garbage UTF-32): `General_Category` `Cn`, script `Unknown`.
pub(super) const DEFAULT_WORD: u16 = 29;

/// Packed category+script word of `cp`: one direct load for the BMP,
/// a two-level trie for the astral planes.
#[inline(always)]
pub(super) fn word(cp: u32) -> u16 {
	if cp < 0x1_0000 {
		let i = (cp as usize) * 2;
		return u16::from_le_bytes([UCD_BMP[i], UCD_BMP[i + 1]]);
	}
	if cp >= 0x11_0000 {
		return DEFAULT_WORD;
	}
	let astral = (cp - 0x1_0000) as usize;
	let block = STAGE1[astral >> 6] as usize;
	// SAFETY: every STAGE1 entry indexes a whole LEAVES block by
	// construction, so the largest in-block offset stays in bounds.
	unsafe { core::hint::assert_unchecked(block * 64 + 0x3f < LEAVES.len()) };
	LEAVES[block * 64 + (astral & 0x3f)]
}

